package com.hbm.satellite;
import com.hbm.world.structure.templates.radio.RTTYSystem;import api.hbm.redstoneoverradio.IRORInteractive;
import net.minecraft.core.HolderLookup;import net.minecraft.nbt.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;
/** Original SatelliteBase state and command/data/cargo lifecycle. Never an orbiting world entity. */
public abstract class SatelliteBase {
 public static final String CHAN_SATLINK="SAT_LINK",CMD_SETTARGET="settarget",CMD_GETTARGET="gettarget",CMD_GETTARGETX="gettargetx",CMD_GETTARGETZ="gettargetz";
 public int targetX,targetZ;public boolean isDirty;public String tx="";public SatelliteDriveType driveInput,driveOutput;public ItemStack[] requestableSlots=new ItemStack[0];
 public int getID(){return SatelliteRegistry.idOf(getClass());}
 public abstract String getType();public abstract Component[] getInfo(ServerLevel world);
 public void writeToNBT(CompoundTag nbt,HolderLookup.Provider lookup){nbt.putInt("targetX",targetX);nbt.putInt("targetZ",targetZ);nbt.putString("tx",tx);if(driveInput!=null)nbt.putInt("driveInput",driveInput.ordinal());if(driveOutput!=null)nbt.putInt("driveOutput",driveOutput.ordinal());nbt.putInt("itemCount",requestableSlots.length);var items=new ListTag();for(int i=0;i<requestableSlots.length;i++){var stack=requestableSlots[i];if(stack==null||stack.isEmpty())continue;var entry=(CompoundTag)stack.save(lookup);entry.putByte("slot",(byte)i);items.add(entry);}nbt.put("requestableSlots",items);}
 public void readFromNBT(CompoundTag nbt,HolderLookup.Provider lookup){targetX=nbt.getInt("targetX");targetZ=nbt.getInt("targetZ");tx=nbt.getString("tx");driveInput=nbt.contains("driveInput")?SatelliteDriveType.safe(nbt.getInt("driveInput")):null;driveOutput=nbt.contains("driveOutput")?SatelliteDriveType.safe(nbt.getInt("driveOutput")):null;requestableSlots=new ItemStack[Math.max(0,nbt.getInt("itemCount"))];java.util.Arrays.fill(requestableSlots,ItemStack.EMPTY);var items=nbt.getList("requestableSlots",Tag.TAG_COMPOUND);for(int i=0;i<items.size();i++){var entry=items.getCompound(i);int slot=entry.getByte("slot")&255;if(slot<requestableSlots.length)requestableSlots[slot]=ItemStack.parseOptional(lookup,entry);}}
 public boolean hasData(ServerLevel world){return driveInput!=null&&driveOutput!=null;}public SatelliteDriveType getOutputData(SatelliteDriveType input){return input==driveInput?driveOutput:null;}public void produceData(SatelliteDriveType input,SatelliteDriveType output){driveInput=input;driveOutput=output;}public void consumeData(){driveInput=null;driveOutput=null;}
 public void onOrbit(ServerLevel world,double x,double y,double z){setTarget((int)Math.floor(x),(int)Math.floor(z));RTTYSystem.broadcast(world,CHAN_SATLINK,"Established connection to "+getType()+" at "+targetX+" / "+targetZ);}
 public void onPartDelivered(ServerLevel world,ItemStack part){}public void onUpdateTick(ServerLevel world){}
 public boolean tryRequestItems(ServerLevel world,int x,int y,int z){if(requestableSlots==null||requestableSlots.length==0)return false;if(!SatelliteCargo.request(world,x,y,z,requestableSlots))return false;requestableSlots=new ItemStack[0];markDirty();return true;}
 public void onCommand(ServerLevel world,String...cmd){onCommandTarget(world,cmd);onCommandImpl(world,cmd);}
 public void onCommandTarget(ServerLevel world,String...cmd){if(cmd.length==0)return;switch(cmd[0]){case CMD_SETTARGET->{if(cmd.length==3){targetX=IRORInteractive.parseInt(cmd[1]);targetZ=IRORInteractive.parseInt(cmd[2]);}if(cmd.length==4){targetX=IRORInteractive.parseInt(cmd[1]);targetZ=IRORInteractive.parseInt(cmd[3]);}}case CMD_GETTARGET->tx=targetX+";"+targetZ;case CMD_GETTARGETX->tx=""+targetX;case CMD_GETTARGETZ->tx=""+targetZ;default->{}}}
 public void setTarget(int x,int z){targetX=x;targetZ=z;}public void onCommandImpl(ServerLevel world,String...cmd){}public void onCoordAction(ServerLevel world,Player player,int x,int y,int z){}public void markDirty(){isDirty=true;}
}
